create_post.beforeRequest:
var body = request.body, tiptap = body.tiptap_body;
if (!(tiptap && typeof tiptap === 'object' && tiptap.body)) {
  if (tiptap && !inputs.text_body) throw new Error("Invalid body input. Provide either 'Post Body (Plain Text)' or a valid 'Tiptap Body JSON'. If both are empty, an empty post will be created.");
  body.tiptap_body = { body: { type: 'doc', content: [{ type: 'paragraph', content: [{ type: 'text', text: inputs.text_body || '' }] }] } };
}
body.status = body.status || 'published';
if (body.published_at && body.status === 'scheduled') body.published_at = new Date(body.published_at).toISOString();
else delete body.published_at;
if ('is_comments_enabled' in body) body.is_comments_closed = !body.is_comments_enabled;
return request;

new_post_created.afterResponse:
// Like the original: pages until an item is older than the last check, and only the first page on the first check.
const since = Number(inputs.lastPollTime) || 0, items = [];
let page = response;
for (let number = 2; ; number++) {
  let older = false;
  for (const item of page.records || []) { if (new Date(item.published_at).getTime() < since) { older = true; break; } items.push(item); }
  if (older || !since || !page.has_next_page) break;
  page = call({method: 'GET', url: '/posts', query: {space_id: inputs.space_id, status: 'published', sort: 'latest', page: String(number), per_page: '60'}, headers: {'Content-Type': 'application/json'}});
}
return items;

